import{f as e,c as a,o as r,a5 as o}from"./chunks/framework.BsEAYNxL.js";const d=JSON.parse('{"title":"AI 编年史 04：智能体 (Agent) 的进化图谱","description":"","frontmatter":{"title":"AI 编年史 04：智能体 (Agent) 的进化图谱","date":"2026-02-14T00:00:00.000Z","categories":["AI","Tech History"],"tags":["Agent","ReAct","AutoGPT","BabyAGI","Prompt Engineering","Chronicle"],"ai_role":"writer","reading_stats":{"count":795,"minutes":2}},"headers":[],"relativePath":"ai-chronicles/05-agentic.md","filePath":"ai-chronicles/05-agentic.md","lastUpdated":null}'),n={name:"ai-chronicles/05-agentic.md"};function i(l,t,s,g,h,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="第一阶段-prompt-engineering-——-咒语时代-2022" tabindex="-1">第一阶段：Prompt Engineering —— 咒语时代 (2022) <a class="header-anchor" href="#第一阶段-prompt-engineering-——-咒语时代-2022" aria-label="Permalink to &quot;第一阶段：Prompt Engineering —— 咒语时代 (2022)&quot;">​</a></h2><p>在 ChatGPT 刚发布时，大家还在研究怎么写 Prompt。</p><h3 id="_1-1-背景与痛点" tabindex="-1">1.1 背景与痛点 <a class="header-anchor" href="#_1-1-背景与痛点" aria-label="Permalink to &quot;1.1 背景与痛点&quot;">​</a></h3><ul><li><strong>Zero-Shot</strong>：直接问，不管模型懂不懂。</li><li><strong>Few-Shot (In-Context Learning)</strong>：给几个例子，让模型照猫画虎。这是 GPT-3 的核心卖点。</li><li><strong><a href="https://arxiv.org/abs/2201.11903" target="_blank" rel="noreferrer">CoT (Chain-of-Thought, 2022)</a></strong>：让模型一步步思考 (&quot;Let&#39;s think step by step&quot;)，显著提升推理能力。 <ul><li><strong><a href="https://arxiv.org/abs/2204.02311" target="_blank" rel="noreferrer">Google PaLM (2022)</a></strong>：证明了 CoT 能解奥数题。</li></ul></li></ul><h3 id="_1-2-局限性" tabindex="-1">1.2 局限性 <a class="header-anchor" href="#_1-2-局限性" aria-label="Permalink to &quot;1.2 局限性&quot;">​</a></h3><ul><li>模型只能在<strong>内部世界</strong>里推理，无法联网，无法用计算器，无法执行代码。</li></ul><h2 id="第二阶段-tool-use与-react-——-睁眼看世界-2023-上半年" tabindex="-1">第二阶段：Tool Use与 ReAct —— 睁眼看世界 (2023 上半年) <a class="header-anchor" href="#第二阶段-tool-use与-react-——-睁眼看世界-2023-上半年" aria-label="Permalink to &quot;第二阶段：Tool Use与 ReAct —— 睁眼看世界 (2023 上半年)&quot;">​</a></h2><p>当 LLM 被赋予了调用 API 的能力，潘多拉魔盒打开了。</p><h3 id="_2-1-核心思想-react-reason-act" tabindex="-1">2.1 核心思想：ReAct (Reason + Act) <a class="header-anchor" href="#_2-1-核心思想-react-reason-act" aria-label="Permalink to &quot;2.1 核心思想：ReAct (Reason + Act)&quot;">​</a></h3><ul><li><strong>论文</strong>：<strong><a href="https://arxiv.org/abs/2210.03629" target="_blank" rel="noreferrer"><em>ReAct: Synergizing Reasoning and Acting in Language Models</em> (Yao et al., 2022)</a></strong></li><li><strong>原理</strong>：让模型先思考 (Thought)，再决定调用什么工具 (Action)，拿到工具结果 (Observation)，再继续思考。 <ul><li>Thought: 用户想查天气。</li><li>Action: <code>Search(&quot;北京天气&quot;)</code></li><li>Observation: &quot;晴，25度&quot;</li><li>Thought: 天气不错。</li><li>Final Answer: &quot;北京今天天气晴朗。&quot;</li></ul></li><li><strong>代表产品</strong>： <ul><li><strong><a href="https://github.com/langchain-ai/langchain" target="_blank" rel="noreferrer">LangChain</a></strong>：将 ReAct 模式封装成了 <code>Agent</code> 概念。</li><li><strong>ChatGPT Plugins</strong>：官方支持联网、订餐、查股票。</li></ul></li></ul><h2 id="第三阶段-autonomous-agent-——-自主规划-2023-下半年" tabindex="-1">第三阶段：Autonomous Agent —— 自主规划 (2023 下半年) <a class="header-anchor" href="#第三阶段-autonomous-agent-——-自主规划-2023-下半年" aria-label="Permalink to &quot;第三阶段：Autonomous Agent —— 自主规划 (2023 下半年)&quot;">​</a></h2><p>如果给 Agent 一个终极目标，让它自己拆解任务、自己反思、自己执行，会发生什么？</p><h3 id="_3-1-背景与痛点" tabindex="-1">3.1 背景与痛点 <a class="header-anchor" href="#_3-1-背景与痛点" aria-label="Permalink to &quot;3.1 背景与痛点&quot;">​</a></h3><ul><li><strong><a href="https://github.com/Significant-Gravitas/AutoGPT" target="_blank" rel="noreferrer">AutoGPT</a></strong>：开源界的狂欢。给定目标“帮我做个网站”，它会自己去 Google 搜教程，自己写代码，自己存文件，自己测试。</li><li><strong><a href="https://github.com/yoheinakajima/babyagi" target="_blank" rel="noreferrer">BabyAGI</a></strong>：任务列表驱动。生成任务 -&gt; 执行任务 -&gt; 根据结果生成新任务 -&gt; 循环。</li><li><strong><a href="https://arxiv.org/abs/2304.03442" target="_blank" rel="noreferrer">Generative Agents (斯坦福小镇, 2023)</a></strong>：25 个 AI 在虚拟小镇里生活、社交、办派对。证明了 Agent 具备社会属性。</li></ul><h3 id="_3-2-挑战与幻灭" tabindex="-1">3.2 挑战与幻灭 <a class="header-anchor" href="#_3-2-挑战与幻灭" aria-label="Permalink to &quot;3.2 挑战与幻灭&quot;">​</a></h3><ul><li><strong>死循环</strong>：AutoGPT 经常卡在某个步骤出不来。</li><li><strong>成本高昂</strong>：跑一个任务要烧几十美金 Token。</li><li><strong>不可靠</strong>：目前的大模型规划能力还不足以支撑长链路任务。</li></ul><h2 id="第四阶段-multi-agent-——-群体智慧-2024-future" tabindex="-1">第四阶段：Multi-Agent —— 群体智慧 (2024 - Future) <a class="header-anchor" href="#第四阶段-multi-agent-——-群体智慧-2024-future" aria-label="Permalink to &quot;第四阶段：Multi-Agent —— 群体智慧 (2024 - Future)&quot;">​</a></h2><p>一个诸葛亮不如三个臭皮匠。既然单个 Agent 不靠谱，那就搞个团队。</p><h3 id="_4-1-核心思想" tabindex="-1">4.1 核心思想 <a class="header-anchor" href="#_4-1-核心思想" aria-label="Permalink to &quot;4.1 核心思想&quot;">​</a></h3><ul><li><strong>角色扮演 (Role Playing)</strong>：让不同的 Agent 扮演不同角色（产品经理、程序员、测试员）。</li><li><strong>SOP (Standard Operating Procedure)</strong>：把复杂的流程拆解成流水线，每个 Agent 只负责一小块。</li><li><strong>辩论与协作</strong>：让 Agent 互相 Review 代码，互相找茬，提升准确率。</li></ul><h3 id="_4-2-代表框架" tabindex="-1">4.2 代表框架 <a class="header-anchor" href="#_4-2-代表框架" aria-label="Permalink to &quot;4.2 代表框架&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/2308.00352" target="_blank" rel="noreferrer">MetaGPT (2023)</a></strong>：模拟软件公司的开发流程。</li><li><strong><a href="https://github.com/joaomdmoura/crewAI" target="_blank" rel="noreferrer">CrewAI</a></strong>：基于角色的任务编排。</li><li><strong><a href="https://arxiv.org/abs/2307.07924" target="_blank" rel="noreferrer">ChatDev (2023)</a></strong>：通过聊天来开发软件。</li></ul><h2 id="_5-拓展-agent-能力分级-l1-l5" tabindex="-1">5. 拓展：Agent 能力分级 (L1-L5) <a class="header-anchor" href="#_5-拓展-agent-能力分级-l1-l5" aria-label="Permalink to &quot;5. 拓展：Agent 能力分级 (L1-L5)&quot;">​</a></h2><p>在工程落地中，我们可以借鉴自动驾驶的分级标准：</p><ul><li><strong>L1 (规则)</strong>：规则驱动的工具调用。</li><li><strong>L2 (推理)</strong>：多路径选择，决策可解释。</li><li><strong>L3 (记忆)</strong>：多轮一致，失败归因。</li><li><strong>L4 (泛化)</strong>：自主学习与策略复用。</li><li><strong>L5 (协作)</strong>：多 Agent 协作。</li></ul><p>级别越高，越难控制。</p><h2 id="_6-总结" tabindex="-1">6. 总结 <a class="header-anchor" href="#_6-总结" aria-label="Permalink to &quot;6. 总结&quot;">​</a></h2><p>Agent 是通往 AGI 的必经之路。未来的软件可能不再是人写的，而是人定义 SOP，让 Agent 团队去实现的。</p>',28)])])}const b=e(n,[["render",i]]);export{d as __pageData,b as default};
